import math
import re
from fractions import Fraction

_NUM = r"(?:\d+(?:\.\d+)?|\.\d+)"

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_COMPONENT_RE = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)\s*")
_BARE_INT_RE = re.compile(r"\d+")
_CLOCK_FIELD_RE = re.compile(r"\d+(?:\.\d+)?")
_ISO_RE = re.compile(
    r"P"
    r"(?:(?P<W>" + _NUM + r")W)?"
    r"(?:(?P<D>" + _NUM + r")D)?"
    r"(?:T"
    r"(?:(?P<H>" + _NUM + r")H)?"
    r"(?:(?P<M>" + _NUM + r")M)?"
    r"(?:(?P<S>" + _NUM + r")S)?"
    r")?"
)


def _round(value: Fraction) -> int:
    return int(math.floor(value + Fraction(1, 2)))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if _BARE_INT_RE.fullmatch(s):
        return int(s)

    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not all(_CLOCK_FIELD_RE.fullmatch(p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        total = Fraction(0)
        for p in parts:
            total = total * 60 + Fraction(p)
        return _round(total)

    if s[0] == "P":
        m = _ISO_RE.fullmatch(s)
        if not m or s == "P" or s.endswith("T"):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        total = Fraction(0)
        for group, unit in (("W", 604800), ("D", 86400), ("H", 3600),
                            ("M", 60), ("S", 1)):
            val = m.group(group)
            if val is not None:
                total += Fraction(val) * unit
        return _round(total)

    pos = 0
    total = Fraction(0)
    count = 0
    while pos < len(s):
        m = _COMPONENT_RE.match(s, pos)
        if not m or m.end() == pos:
            raise ValueError(f"invalid duration: {text!r}")
        num, unit = m.group(1), m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {unit!r} in {text!r}")
        total += Fraction(num) * _UNITS[unit]
        count += 1
        pos = m.end()
    if count == 0:
        raise ValueError("empty duration")
    return _round(total)

